\textbf{Question:} What are the trends in China’s computing power market?

\textbf{Outline:}

\textcolor{TitleRed}{1. Overview of China’s Computing Power Market}

\textcolor{TitleRed}{1.1 Market Size and Growth [citation]1, 2, 3, 4, 9, 18[/citation]}

\textcolor{TitleRed}{1.1.1 Total Computing Power Capacity}
\begin{itemize}[leftmargin=1em, listparindent=\parindent]
\item China’s total computing power capacity reached 280 EFLOPS in 2024. [citation]1, 4[/citation]
\item It is expected to exceed 300 EFLOPS in 2025 and 2,500 EFLOPS by 2030. [citation]2, 9[/citation]
\item China’s computing power capacity has recorded an average annual growth rate of 48\% over the past eight years. [citation]22[/citation]
\end{itemize}

\textcolor{TitleRed}{1.1.2 Intelligent Computing Power Capacity}
\begin{itemize}[leftmargin=1em, listparindent=\parindent]
\item Intelligent computing power capacity reached 725.3 EFLOPS in 2024, representing year-on-year growth of 74.1\%. [citation]1, 14[/citation]
\item It is expected to reach 1,037.3 EFLOPS in 2025, an increase of 43\%. [citation]1, 3[/citation]
\item It is projected to reach 2,781.9 EFLOPS by 2028, with a CAGR of 46.2\% from 2023 to 2028. [citation]3[/citation]
\end{itemize}

\textcolor{TitleRed}{1.1.3 General-Purpose Computing Power Capacity}
\begin{itemize}[leftmargin=1em, listparindent=\parindent]
\item General-purpose computing power capacity reached 71.5 EFLOPS in 2024, up 20.6\% year on year. [citation]1[/citation]
\item It is expected to reach 85.8 EFLOPS in 2025, representing growth of 20\%. [citation]1[/citation]
\item The CAGR from 2023 to 2028 is projected to be 18.8\%. [citation]1, 3[/citation]
\end{itemize}

\textcolor{TitleRed}{1.1.4 Market Size by Value}
\begin{itemize}[leftmargin=1em, listparindent=\parindent]
\item China’s computing power market is expected to reach RMB 835.1 billion in 2025, representing year-on-year growth of more than 30\%. [citation]2, 4[/citation]
\item The market is projected to reach RMB 1.05 trillion in 2026 and nearly RMB 2 trillion by 2030. [citation]2, 4[/citation]
\item The AI server market is expected to reach RMB 296.346 billion in 2025, accounting for 67.01\% of the computing server market. [citation]18[/citation]
\end{itemize}

\textcolor{TitleRed}{1.2 Global Competitiveness and Ranking [citation]16, 22[/citation]}

\textcolor{TitleRed}{1.2.1 Global Computing Power Ranking}
\begin{itemize}[leftmargin=1em, listparindent=\parindent]
\item China ranks second globally in computing power, with a score of 70, behind only the United States, which scores 77. [citation]16[/citation]
\item China and the United States are both classified as “front-runners,” with China recording the largest improvement worldwide. [citation]16[/citation]
\end{itemize}

\textcolor{TitleRed}{1.2.2 Global Position in Intelligent Computing Power}
\begin{itemize}[leftmargin=1em, listparindent=\parindent]
\item By the end of 2025, China’s intelligent computing power capacity is expected to reach 1.59 million PFLOPS, ranking second globally. [citation]16, 22[/citation]
\item China has built 42 intelligent computing clusters containing at least 10,000 accelerator cards each, while its operational computing facilities contain more than 13.73 million standard racks. [citation]16, 22[/citation]
\end{itemize}

\textcolor{TitleRed}{2. Structural Characteristics of the Computing Power Market}

\textcolor{TitleRed}{2.1 Computing Power Mix [citation]1, 3, 13[/citation]}

\textcolor{TitleRed}{2.1.1 Shares of Training and Inference Computing}
\begin{itemize}[leftmargin=1em, listparindent=\parindent]
\item In 2023, training workloads accounted for 58.7\% of computing power demand, while inference workloads accounted for 41.3\%. [citation]13[/citation]
\item The share of inference demand is expected to reach 72.6\% in 2027 and 73.0\% in 2028. [citation]13[/citation]
\item Demand for inference computing has significantly greater growth potential than training computing and is expected to become the primary source of future growth. [citation]13[/citation]
\end{itemize}

\textcolor{TitleRed}{2.1.2 Intelligent and General-Purpose Computing Mix}
\begin{itemize}[leftmargin=1em, listparindent=\parindent]
\item In 2024, intelligent computing accounted for 32\% of total computing power, while general-purpose computing accounted for 68\%. [citation]5[/citation]
\item The growth rate of intelligent computing power, at 74.1\%, significantly exceeded the 20.6\% growth rate of general-purpose computing power. [citation]1[/citation]
\end{itemize}

\textcolor{TitleRed}{2.2 Industry Chain Structure [citation]4, 12, 15[/citation]}

\textcolor{TitleRed}{2.2.1 Upstream: Core Hardware and Equipment}
\begin{itemize}[leftmargin=1em, listparindent=\parindent]
\item AI chips: Cambricon, Huawei Ascend, Baidu Kunlun, and Hygon Information Technology. [citation]12, 15[/citation]
\item Servers: Inspur Information, Sugon, H3C, and Nettrix. [citation]12, 15, 18[/citation]
\item Storage equipment: Yangtze Memory Technologies Co. [citation]15[/citation]
\item Network equipment: Innolight Technology and Ruijie Networks. [citation]15[/citation]
\end{itemize}

\textcolor{TitleRed}{2.2.2 Midstream: Data Centres and Computing Services}
\begin{itemize}[leftmargin=1em, listparindent=\parindent]
\item Data centre operators: VNET Group and Range Intelligent Computing Technology. [citation]15[/citation]
\item Cloud computing services: China Telecom Cloud, Alibaba Cloud, Tencent Cloud, and Huawei Cloud. [citation]12, 15[/citation]
\item Computing power scheduling: Sugon and China Telecom. [citation]15[/citation]
\end{itemize}

\textcolor{TitleRed}{2.2.3 Downstream: Industry Applications}
\begin{itemize}[leftmargin=1em, listparindent=\parindent]
\item In the internet sector, general-purpose computing accounts for 39\%, while intelligent computing accounts for 53\%. [citation]7[/citation]
\item Other major application sectors include finance, manufacturing, telecommunications, government, healthcare, and education. [citation]7, 15[/citation]
\end{itemize}

\textcolor{TitleRed}{2.3 Regional Distribution [citation]6, 11, 15[/citation]}

\textcolor{TitleRed}{2.3.1 Layout of National Computing Hub Nodes}
\begin{itemize}[leftmargin=1em, listparindent=\parindent]
\item China has established eight national computing hub nodes: Beijing–Tianjin–Hebei, the Yangtze River Delta, the Guangdong–Hong Kong–Macao Greater Bay Area, Chengdu–Chongqing, Guizhou, Inner Mongolia, Gansu, and Ningxia. [citation]6[/citation]
\item More than 60\% of the country’s newly added computing power is located in these national hub nodes. [citation]6[/citation]
\end{itemize}

\textcolor{TitleRed}{2.3.2 Distribution Between Eastern and Western China}
\begin{itemize}[leftmargin=1em, listparindent=\parindent]
\item Computing capacity in eastern China is largely operating at full capacity and fully leased, while supply and demand conditions in western China are relatively less constrained. [citation]11[/citation]
\item Western China focuses primarily on high-performance servers for training workloads, while eastern China focuses on low-latency servers for inference workloads. [citation]18[/citation]
\end{itemize}

\textcolor{TitleRed}{3. Development Trends in the Computing Power Market}

\textcolor{TitleRed}{3.1 Transition Towards Intelligent Computing [citation]1, 3, 13, 14[/citation]}

\textcolor{TitleRed}{3.1.1 Rapid Growth of Intelligent Computing Power}
\begin{itemize}[leftmargin=1em, listparindent=\parindent]
\item The CAGR of intelligent computing power, at 46.2\%, is significantly higher than the 18.8\% CAGR of general-purpose computing power. [citation]1, 3[/citation]
\item Newly added intelligent computing power is expected to exceed 100 EFLOPS in 2025. [citation]4[/citation]
\end{itemize}

\textcolor{TitleRed}{3.1.2 Inference Computing as a New Growth Driver}
\begin{itemize}[leftmargin=1em, listparindent=\parindent]
\item The share of inference computing is expected to rise from 41.3\% in 2023 to 73.0\% in 2028. [citation]13[/citation]
\item Lightweight large language models such as DeepSeek are driving rapid expansion in inference applications. [citation]13[/citation]
\end{itemize}

\textcolor{TitleRed}{3.2 Domestic Substitution [citation]5, 12[/citation]}

\textcolor{TitleRed}{3.2.1 Rising Self-Sufficiency in Domestic Chips}
\begin{itemize}[leftmargin=1em, listparindent=\parindent]
\item China’s self-sufficiency rate for AI GPUs increased from less than 10\% in 2020 to approximately 34\% in 2024. [citation]5[/citation]
\item The self-sufficiency rate for domestically produced AI chips is expected to reach 82\% by 2027. [citation]5[/citation]
\end{itemize}

\textcolor{TitleRed}{3.2.2 Market Share of Domestic Servers}
\begin{itemize}[leftmargin=1em, listparindent=\parindent]
\item More than 900,000 domestically produced servers were sold in 2024, representing approximately 20\% of the market. [citation]5[/citation]
\item Domestic chips are progressing from being merely “usable” to becoming genuinely competitive and user-friendly. [citation]5[/citation]
\end{itemize}

\textcolor{TitleRed}{3.3 Green Development [citation]6, 8, 18[/citation]}

\textcolor{TitleRed}{3.3.1 Adoption of Liquid Cooling Technology}
\begin{itemize}[leftmargin=1em, listparindent=\parindent]
\item The liquid cooling market for intelligent computing centres reached RMB 18.4 billion in 2024 and is expected to reach RMB 130 billion by 2029. [citation]8[/citation]
\item More than 50\% of data centre projects are expected to adopt liquid cooling technology in 2025. [citation]8[/citation]
\end{itemize}

\textcolor{TitleRed}{3.3.2 Energy Consumption and PUE Indicators}
\begin{itemize}[leftmargin=1em, listparindent=\parindent]
\item Data centres consumed a total of 150 billion kWh of electricity in 2023, accounting for 1.6\% of China’s total electricity consumption. [citation]8[/citation]
\item The national average power usage effectiveness, or PUE, was 1.48, while the average PUE across the eight national computing hub nodes reached 1.257. [citation]8[/citation]
\item By 2030, annual electricity consumption by computing centres is expected to reach 600 billion kWh, accounting for 5\%–6\% of national electricity consumption. [citation]9[/citation]
\end{itemize}

\textcolor{TitleRed}{3.3.3 Coordination with Green Electricity}
\begin{itemize}[leftmargin=1em, listparindent=\parindent]
\item Green electricity accounts for more than 80\% of the power used by newly built data centres in the national computing hub nodes. [citation]6[/citation]
\item China is promoting the coordinated geographical deployment of green electricity and computing power. [citation]19[/citation]
\end{itemize}

\textcolor{TitleRed}{3.4 Innovation in Computing Service Models [citation]14, 20, 21[/citation]}

\textcolor{TitleRed}{3.4.1 Computing Power Leasing Market}
\begin{itemize}[leftmargin=1em, listparindent=\parindent]
\item The intelligent computing power leasing market reached approximately RMB 147.96 billion in 2024. [citation]14[/citation]
\item It is expected to grow to RMB 211.61 billion in 2025. [citation]14[/citation]
\item The average unit price of computing power is RMB 17,000 per PFLOPS per month. [citation]14[/citation]
\end{itemize}

\textcolor{TitleRed}{3.4.2 Computing Voucher Subsidy Policies}
\begin{itemize}[leftmargin=1em, listparindent=\parindent]
\item Beijing provides subsidies covering up to 50\% of eligible expenses, with a maximum subsidy of RMB 30 million for new-type research and development institutions. [citation]20[/citation]
\item Shanghai has issued RMB 600 million in computing vouchers, offering support of up to 100\% and a maximum allocation of RMB 1 million per recipient. [citation]21[/citation]
\item Many regions have introduced combined subsidy programmes involving computing vouchers, data vouchers, and model vouchers. [citation]21[/citation]
\end{itemize}

\textcolor{TitleRed}{4. Supply and Demand Dynamics}

\textcolor{TitleRed}{4.1 Structural Imbalances Between Supply and Demand [citation]11[/citation]}

\textcolor{TitleRed}{4.1.1 Surplus of General-Purpose Computing Power}
\begin{itemize}[leftmargin=1em, listparindent=\parindent]
\item Some older general-purpose computing centres remain idle, while the average rack deployment rate in internet data centres is only 58\%. [citation]11[/citation]
\item PUE exceeds 2.5 in some regions, indicating low energy efficiency. [citation]11[/citation]
\end{itemize}

\textcolor{TitleRed}{4.1.2 Shortage of Intelligent Computing Power}
\begin{itemize}[leftmargin=1em, listparindent=\parindent]
\item China is expected to require three million GPUs in 2025, while production capacity is unlikely to meet demand. [citation]11[/citation]
\item A significant supply gap remains in high-end intelligent computing power. [citation]11[/citation]
\end{itemize}

\textcolor{TitleRed}{4.2 Computing Power Utilisation [citation]5, 11[/citation]}

\textcolor{TitleRed}{4.2.1 Low Overall Utilisation}
\begin{itemize}[leftmargin=1em, listparindent=\parindent]
\item Actual GPU utilisation at intelligent computing centres remains low, falling below 32\% in some cases. [citation]5[/citation]
\item The average rack utilisation rate across the computing infrastructure industry is below 60\%. [citation]11[/citation]
\end{itemize}

\textcolor{TitleRed}{4.2.2 Causes of Supply–Demand Mismatches}
\begin{itemize}[leftmargin=1em, listparindent=\parindent]
\item Computing demand is evolving rapidly, while underlying hardware is undergoing continuous generational replacement. [citation]11[/citation]
\item Limited market understanding among both buyers and sellers contributes to resource mismatches. [citation]11[/citation]
\end{itemize}

\textcolor{TitleRed}{5. Policy Environment and Planning}

\textcolor{TitleRed}{5.1 National Strategic Planning [citation]6, 10, 19[/citation]}

\textcolor{TitleRed}{5.1.1 East Data, West Computing Project}
\begin{itemize}[leftmargin=1em, listparindent=\parindent]
\item The project was launched in 2022 to establish an integrated national computing power network. [citation]5, 6[/citation]
\item By 2025, China aims to establish urban computing networks with latency of 1 millisecond, regional computing networks with latency of 5 milliseconds, and cross-hub computing networks with latency of 20 milliseconds. [citation]6[/citation]
\end{itemize}

\textcolor{TitleRed}{5.1.2 The 15th Five-Year Plan, 2026–2030}
\begin{itemize}[leftmargin=1em, listparindent=\parindent]
\item The share of value added by core digital economy industries in GDP is expected to rise from 10.5\% to 12.5\%. [citation]19[/citation]
\item China will promote market-oriented construction and operation of computing infrastructure and support government procurement of computing services and computing power leasing. [citation]19[/citation]
\item China will assess and plan the construction of ultra-large-scale intelligent computing clusters. [citation]19[/citation]
\end{itemize}

\textcolor{TitleRed}{5.2 Fiscal Support [citation]10, 20, 21[/citation]}

\textcolor{TitleRed}{5.2.1 Number and Coverage of Policies}
\begin{itemize}[leftmargin=1em, listparindent=\parindent]
\item More than ten major national-level policies were introduced between 2023 and 2025. [citation]10[/citation]
\item These policies cover computing infrastructure, the “AI Plus” initiative, data industry development, and related areas. [citation]10[/citation]
\end{itemize}

\textcolor{TitleRed}{5.2.2 Corporate AI Investment}
\begin{itemize}[leftmargin=1em, listparindent=\parindent]
\item Leading technology companies are expected to invest a combined total of approximately RMB 450 billion in AI computing power in 2025. [citation]10[/citation]
\item Investment and financing in the artificial intelligence sector exceeded RMB 100 billion in 2024. [citation]10[/citation]
\end{itemize}

\textcolor{TitleRed}{6. Market Challenges and Risks}

\textcolor{TitleRed}{6.1 Technical Challenges [citation]5, 17[/citation]}

\textcolor{TitleRed}{6.1.1 Chip Sanctions and Export Restrictions}
\begin{itemize}[leftmargin=1em, listparindent=\parindent]
\item The United States has tightened restrictions on the sale of AI chips to China, contributing to a severe shortage of computing power. [citation]17[/citation]
\item Domestic research and development teams have been forced to slow the development of large language models. [citation]17[/citation]
\end{itemize}

\textcolor{TitleRed}{6.1.2 Ecosystem Barriers}
\begin{itemize}[leftmargin=1em, listparindent=\parindent]
\item NVIDIA’s CUDA ecosystem accounts for more than 90\% of the global market. [citation]17[/citation]
\item Migrating to domestic chips involves high costs and lengthy adaptation cycles. [citation]17[/citation]
\end{itemize}

\textcolor{TitleRed}{6.2 Industry Challenges [citation]5, 17[/citation]}

\textcolor{TitleRed}{6.2.1 Insufficient Industry Chain Coordination}
\begin{itemize}[leftmargin=1em, listparindent=\parindent]
\item Adaptation between the computing layer and the model layer remains inadequate, while the model layer is poorly connected with the application layer. [citation]17[/citation]
\item Supply–demand mismatches and functional disconnections exist across different parts of the industry chain. [citation]17[/citation]
\end{itemize}

\textcolor{TitleRed}{6.2.2 Business Model Constraints}
\begin{itemize}[leftmargin=1em, listparindent=\parindent]
\item Users have not yet developed established payment habits, leaving the market dependent on government subsidies. [citation]17[/citation]
\item Scaling and replicating products remains difficult due to the absence of standardised product systems. [citation]17[/citation]
\end{itemize}

\textcolor{TitleRed}{6.3 Infrastructure Challenges [citation]5[/citation]}

\textcolor{TitleRed}{6.3.1 Management of Large-Scale Computing Interconnections}
\begin{itemize}[leftmargin=1em, listparindent=\parindent]
\item Clusters containing more than 10,000 accelerator cards face challenges in controlling hardware failure rates and system faults. [citation]5[/citation]
\item China has limited experience in managing and interconnecting computing resources at such a large scale. [citation]5[/citation]
\end{itemize}

\textcolor{TitleRed}{6.3.2 High Requirements for Supporting Infrastructure}
\begin{itemize}[leftmargin=1em, listparindent=\parindent]
\item Power density per rack has increased from 7–8 kW to 40–60 kW. [citation]5[/citation]
\item This places substantially higher requirements on electricity supply, structural load-bearing capacity, and heat dissipation. [citation]5[/citation]
\end{itemize}

\textcolor{TitleRed}{7. Future Outlook and Opportunities}

\textcolor{TitleRed}{7.1 Market Size Forecasts [citation]2, 4, 9, 18[/citation]}

\textcolor{TitleRed}{7.1.1 Near-Term Forecasts, 2025–2026}
\begin{itemize}[leftmargin=1em, listparindent=\parindent]
\item The computing power market is expected to reach RMB 1.05 trillion in 2026. [citation]2, 4[/citation]
\item Intelligent computing power capacity is expected to reach 1,460.3 EFLOPS in 2026. [citation]22[/citation]
\end{itemize}

\textcolor{TitleRed}{7.1.2 Long-Term Forecasts for 2030}
\begin{itemize}[leftmargin=1em, listparindent=\parindent]
\item The computing power market is expected to approach RMB 2 trillion by 2030. [citation]2, 4[/citation]
\item Total computing power capacity is expected to exceed 2,500 EFLOPS by 2030. [citation]9[/citation]
\item The direct output of AI-related industries is expected to reach RMB 2 trillion, driving more than RMB 20 trillion in upstream and downstream output. [citation]9[/citation]
\end{itemize}

\textcolor{TitleRed}{7.2 Technology Development Trends [citation]5, 18[/citation]}

\textcolor{TitleRed}{7.2.1 Heterogeneous Technology Architectures}
\begin{itemize}[leftmargin=1em, listparindent=\parindent]
\item CPUs, GPUs, NPUs, FPGAs, and other chips will become increasingly integrated and coordinated. [citation]18[/citation]
\item China is also developing emerging architectures such as quantum computing, in-memory computing, and photonic computing. [citation]5[/citation]
\end{itemize}

\textcolor{TitleRed}{7.2.2 Customised Product Formats}
\begin{itemize}[leftmargin=1em, listparindent=\parindent]
\item Dedicated and customised products will be developed for AI training, inference, edge computing, and other specialised applications. [citation]18[/citation]
\item Inference is expected to become the primary workload for AI servers. [citation]13[/citation]
\end{itemize}

\textcolor{TitleRed}{7.3 Industry Opportunities [citation]14, 19[/citation]}

\textcolor{TitleRed}{7.3.1 Computing Power Services Market}
\begin{itemize}[leftmargin=1em, listparindent=\parindent]
\item The intelligent computing services market reached USD 5 billion in 2024 and is expected to grow to USD 7.95 billion in 2025. [citation]3[/citation]
\item The market is projected to record a CAGR of 57.3\% from 2023 to 2028. [citation]3[/citation]
\end{itemize}

\textcolor{TitleRed}{7.3.2 Expansion of Industry Applications}
\begin{itemize}[leftmargin=1em, listparindent=\parindent]
\item Computing power is expanding rapidly beyond the internet sector into industrial manufacturing, urban governance, smart retail, and other fields. [citation]7[/citation]
\item The development of “industrial brains” and “city brains” has begun to achieve meaningful scale. [citation]7[/citation]
\end{itemize}
\end{tcolorbox}
```

