 \begin{itemize}
 \item \texttt{queries} (\emph{List[String]}): A list of 1--5 concise search queries. Each query should be a short semantic phrase or question rather than a long paragraph.
 \end{itemize}
 \item \textbf{Output:} Search results corresponding to each submitted query.
\end{itemize}

\vspace{0.8em}

\textbf{Tool 2: \texttt{web\_fetch\_and\_summary}}

\begin{itemize}
 \item \textbf{Description:} Retrieve the content of a webpage and summarize it according to a specified information objective.
 \item \textbf{Input Parameters:}
 \begin{itemize}
 \item \texttt{url} (\emph{String}): URL of the webpage.
 \item \texttt{goal} (\emph{String}): The information objective guiding the extraction and summarization.
 \end{itemize}
 \item \textbf{Output:} A goal-oriented summary of the webpage content.
\end{itemize}
\end{tcolorbox}
